query:
SELECT DISTINCT ?artist ?name ?mbid ?desc ?matched ?links WHERE {
      VALUES ?matched { "pop music"@en "rock music"@en "pop rock"@en "indie pop"@en "Italian pop"@en "musica leggera"@en "canzone"@en "Italo disco"@en }
      ?genre rdfs:label ?matched.
      ?artist wdt:P136 ?genre; wdt:P434 ?mbid; rdfs:label ?name.
      FILTER(LANG(?name)="en")
      {{?artist wdt:P27 wd:Q38} UNION {?artist wdt:P495 wd:Q38}}
      FILTER(EXISTS {?artist wdt:P31 wd:Q5} || EXISTS {?artist wdt:P31/wdt:P279* wd:Q2088357})
      OPTIONAL {?artist schema:description ?desc. FILTER(LANG(?desc)="en")}
      OPTIONAL {?artist wikibase:sitelinks ?links}
    } ORDER BY DESC(?links) ?name LIMIT 900
